INSERT INTO `shop_product` (`id_product`, `name`, `description`, `picture_small_url`, `picture_big_url`, `picture_id`, `price`, `vat`, `quantity`, `status`) VALUES
	(3190, 'MIMIO', ' \r\nSpełnia oczekiwania najbardziej wymagających wykładowców!\r\n\r\n- do zastosowania na dowolnej suchościeralnej białej tablicy (lub innej podobnej powierzchni projekcyjnej)\r\n- ogromna interaktywna powierzchnia prezentacyjna - aż do ponad 3 m\r\n- lekka, przenośna i prosta w montażu\r\n- potężna baza interaktywnych materiałów do wykorzystania na prowadzonych przez Ciebie zajęciach i prezentacjach\r\n- wiele dostępnych formatów zapisu pliku ( .html, .pdf, .gif, .jpg, .tif, .bmp, .png, .wmf, .emf )\r\n\r\nUmów się na PREZENTACJĘ! \r\ntel. kom.: 0693 469 114', 'product_image/MIMIO_interactive_main_s.jpg', 'product_image/MIMIO_interactive_main.jpg', NULL, 2250.0000, 5, 1, 'ACTIVE'),
	(3191, 'MIMIO + capture', 'Zapamiętuj i udostępniaj wszystkie notatki robione na białej tablicy!\r\n\r\n- możliwość zapamiętania do 10 godz. w pamięci urządzenia\r\n- ogromna interaktywna powierzchnia prezentacyjna - aż do ponad 3 m\r\n- lekka, przenośna i prosta w montażu\r\n- potężna baza interaktywnych materiałów do wykorzystania na prowadzonych przez Ciebie zajęciach i prezentacjach\r\n- wiele dostępnych formatów zapisu pliku ( .html, .pdf, .gif, .jpg, .tif, .bmp, .png, .wmf, .emf )\r\n\r\nUmów się na PREZENTACJĘ! \r\ntel. kom.: 0693 469 114\r\n', 'product_image/MIMIO_capture_capture_main2_s.jpg', 'product_image/MIMIO_capture_capture_main2.jpg', NULL, 2950.0000, 5, 1, 'ACTIVE'),
	(3192, 'KARTY DYDAKTYCZNE - FLASHCARDS OWOCE ENGLISH VERSION', 'Karty dydaktyczne Flashcards owoce, 36 kart w kartonowym eleganckim pudełku. Wersja angielska. Karty o wymiarach 210x148 mm i łącznej wadze 0,45 kg, wykonane są ze stosunkowo sztywnego kredowego papieru i pokryte lakierem zabezpieczającym przed pozostawianiem odcisk&oacute;w palc&oacute;w i lekkim zabrudzeniem. Kolorowe zdjęcia owoc&oacute;w zamieszczone na kartach zostały wykonane w dużej rozdzielczości, a ich nazwy napisane są czarną czcionką, widoczną z daleka. Karty przeznaczone są gł&oacute;wnie dla nauczycieli nauczania początkowego, logoped&oacute;w, lektor&oacute;w język&oacute;w obcych, ale r&oacute;wnie dobrze mogą być używane przez nauczycieli innych przedmiot&oacute;w, uczni&oacute;w i student&oacute;w.\r\n\r\nLista owoc&oacute;w znajdujących się w zestawie: agrest, ananas, arbuz, awokado, banan, brzoskwinia, cytryna, czarna porzeczka, czereśnia, czerwona porzeczka, daktyl, figa, granat, grejpfrut, gruszka, jabłko, jagoda, jeżyna, kasztan jadalny, kiwi, liczi, limetka, malina, mandarynka, mango, melon, morela, nektarynka, orzech kokosowy, pomarańcza, poziomka, śliwka, truskawka, winogrona, wiśnia, żurawina. (* część owoc&oacute;w przedstawionych jest w liczbie pojedynczej, część w liczbie mnogiej)', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_OWOCE_ENGLISH_VERSION_layout_owoce_s.jpg', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_OWOCE_ENGLISH_VERSION_layout_owoce.jpg', NULL, 44.0000, 5, 15, 'ACTIVE'),
	(3193, 'KARTY DYDAKTYCZNE - FLASHCARDS WARZYWA ENGLISH VERSION', 'Karty dydaktyczne Flashcards Warzywa wersja angielska.45 kart A5 w kartonowym pudełku.\r\nKarty o wymiarach 210x148 mm i łącznej wadze 0,55 kg wykonane są ze stosunkowo sztywnego kredowego papieru i pokryte lakierem zabezpieczającym przed pozostawianiem odcisk&oacute;w palc&oacute;w i lekkim zabrudzeniem. Kolorowe zdjęcia warzyw zamieszczone na kartach zostały wykonane w dużej rozdzielczości, a ich nazwy napisane są czarną czcionką, widoczną z daleka. Karty przeznaczone są gł&oacute;wnie dla nauczycieli nauczania początkowego, logoped&oacute;w, lektor&oacute;w język&oacute;w obcych, ale r&oacute;wnie dobrze mogą być używane przez nauczycieli innych przedmiot&oacute;w, uczni&oacute;w i student&oacute;w. Obecnie dostępne są w wersjach angielskiej i niemieckiej, lecz wkr&oacute;tce ukażą się w wersjach: polskiej, francuskiej, hiszpańskiej i włoskiej.\r\n\r\nLista warzyw znajdujących się w zestawie: bakłażan, b&oacute;b, brokuł, brukselka, burak, cebula, cebulka zielona, chrzan, ciecierzyca, cukinia, cykoria, czosnek, dynia, fasola, fasolka szparagowa (ż&oacute;łta), groch, kalafior, kalarepa, kapusta biała, kapusta czerwona, kapusta pekińska, kiełki, koper włoski, kukurydza, marchew, og&oacute;rek, oliwka, papryka, papryka chili, patison, pietruszka korzeń, pomidor, por, rzepa, rzeżucha, rzodkiewka, sałata, seler korzeń, seler naciowy, soczewica, soja, szczypior, szparag, szpinak, ziemniak.\r\n\r\n* część warzyw przedstawionych jest w liczbie pojedynczej, część w liczbie mnogiej', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_WARZYWA_ENGLISH_VERSION_layout_www_warzywa_s.jpg', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_WARZYWA_ENGLISH_VERSION_layout_www_warzywa.jpg', NULL, 47.0000, 5, 15, 'ACTIVE'),
	(3194, 'KARTY DYDAKTYCZNE - FLASHCARDS OWOCE DEUTSCHE VERSION', 'Karty dydaktyczne Flashcards owoce, 36 kart w kartonowym eleganckim pudełku. Wersja niemiecka. Karty o wymiarach 210x148 mm i łącznej wadze 0,45 kg, wykonane są ze stosunkowo sztywnego kredowego papieru i pokryte lakierem zabezpieczającym przed pozostawianiem odcisk&oacute;w palc&oacute;w i lekkim zabrudzeniem. Kolorowe zdjęcia owoc&oacute;w zamieszczone na kartach zostały wykonane w dużej rozdzielczości, a ich nazwy napisane są czarną czcionką, widoczną z daleka. Karty przeznaczone są gł&oacute;wnie dla nauczycieli nauczania początkowego, logoped&oacute;w, lektor&oacute;w język&oacute;w obcych, ale r&oacute;wnie dobrze mogą być używane przez nauczycieli innych przedmiot&oacute;w, uczni&oacute;w i student&oacute;w.\r\n\r\nLista owoc&oacute;w znajdujących się w zestawie: agrest, ananas, arbuz, awokado, banan, brzoskwinia, cytryna, czarna porzeczka, czereśnia, czerwona porzeczka, daktyl, figa, granat, grejpfrut, gruszka, jabłko, jagoda, jeżyna, kasztan jadalny, kiwi, liczi, limetka, malina, mandarynka, mango, melon, morela, nektarynka, orzech kokosowy, pomarańcza, poziomka, śliwka, truskawka, winogrona, wiśnia, żurawina. (* część owoc&oacute;w przedstawionych jest w liczbie pojedynczej, część w liczbie mnogiej)', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_OWOCE_DEUTSCHE_VERSION_layout_owoce_s.jpg', 'product_image/KARTY_DYDAKTYCZNE_-_FLASHCARDS_OWOCE_DEUTSCHE_VERSION_layout_owoce.jpg', NULL, 44.0000, 5, 15, 'ACTIVE'),
	(3195, 'KARTY DYDAKTYCZNE - FLASHCARDS WARZYWA DEUTSCHE VERSION', 'Karty dydaktyczne Flashcards Warzywa wersja NIEMIECKA.45 kart A5 w kartonowym pudełku.\r\nKarty o wymiarach 210x148 mm i łącznej wadze 0,55 kg wykonane są ze stosunkowo sztywnego kredowego papieru i pokryte lakierem zabezpieczającym przed pozostawianiem odcisk&oacute;w palc&oacute;w i lekkim zabrudzeniem. Kolorowe zdjęcia warzyw zamieszczone na kartach zostały wykonane w dużej rozdzielczości, a ich nazwy napisane są czarną czcionką, widoczną z daleka. Karty przeznaczone są gł&oacute;wnie dla nauczycieli nauczania początkowego, logoped&oacute;w, lektor&oacute;w język&oacute;w obcych, ale r&oacute;wnie dobrze mogą być używane przez nauczycieli innych przedmiot&oacute;w, uczni&oacute;w i student&oacute;w. Obecnie dostępne są w wersjach angielskiej i niemieckiej, lecz wkr&oacute;tce ukażą się w wersjach: polskiej, francuskiej, hiszpańskiej i włoskiej.\r\n\r\nLista warzyw znajdujących się w zestawie: bakłażan, b&oacute;b, brokuł, brukselka, burak, cebula, cebulka zielona, chrzan, ciecierzyca, cukinia, cykoria, czosnek, dynia, fasola, fasolka szparagowa (ż&oacute;łta), groch, kalafior, kalarepa, kapusta biała, kapusta czerwona, kapusta pekińska, kiełki, koper włoski, kukurydza, marchew, og&oacute;rek, oliwka, papryka, papryka chili, patison, pietruszka korzeń, pomidor, por, rzepa, rzeżucha, rzodkiewka, sałata, seler korzeń, seler naciowy, soczewica, soja, szczypior, szparag, szpinak, ziemniak.\r\n\r\n* część warzyw przedstawionych jest w liczbie pojedynczej, część w liczbie mnogiej', 'product_image/_layout_www_warzywa_s.jpg', 'product_image/_layout_www_warzywa.jpg', NULL, 47.0000, 5, 15, 'ACTIVE'),
	(3196, 'A Concise Guide to Psycholinguistics', 'The present Concise Guide to Psycholinguistics provides a brief introduction to the affluent field of psycholinguistics by means of an encyclopaedic discussion of a number of concepts and problems relating to this discipline of linguistic endeavour. New students and general readers can discover for themselves what psycholinguistics is all about and what disciplines surround it and collaborate with it. Students of linguistics will find in the Guide a handy presentation of some of the background concepts which may facilitate the reader\\\'s grasp of psycholinguistics. Likewise, a select bibliography, which accompanies the text, refers the reader to significant studies in the areas covered by the Guide. By and large, by providing a discussion of entries which encompass a large spectrum of problems dealt with by psycholinguistics, the Guide constitutes a compendium of both theory and research on psycholinguistics, one of the most active and interesting research areas in linguistics today.\r\n', 'product_image/A_Concise_Guide_to_Psycholinguistics_Puppel_s.jpg', 'product_image/A_Concise_Guide_to_Psycholinguistics_Puppel.jpg', NULL, 24.0000, 5, 50, 'ACTIVE'),
	(3197, 'A Short Grammar of Middle English', 'A Short Grammar of Middle English to podręcznik akademicki dla studentów filologii angielskiej. Autor w sposób całościowy omawia zagadnienia średniowiecznego języka angielskiego (pisownia, fonologia, morfologia). Praca napisana jest z perspektywy strukturalnego podejścia do języka. Wykład autora opatrzony jest licznymi przykładami, tablicami form gramatycznych, odsyłaczami do literatury przedmiotu itp. Podręcznik wykorzytywany jest przy nauczaniu przedmiotu historia języka angielskiego na studiach zawodowych i magisterskich.A Short Grammar of Middle English to podręcznik akademicki dla studentów filologii angielskiej. Autor w sposób całościowy omawia zagadnienia średniowiecznego języka angielskiego (pisownia, fonologia, morfologia). Praca napisana jest z perspektywy strukturalnego podejścia do języka. Wykład autora opatrzony jest licznymi przykładami, tablicami form gramatycznych, odsyłaczami do literatury przedmiotu itp. Podręcznik wykorzytywany jest przy nauczaniu przedmiotu historia języka angielskiego na studiach zawodowych i magisterskich.', 'product_image/A_Short_Grammar_of_Middle_English_a_short_s.jpg', 'product_image/A_Short_Grammar_of_Middle_English_a_short.jpg', NULL, 22.0000, 5, 500, 'ACTIVE'),
	(3198, 'English Phonetics for Polses', 'This is an entirely original textbook of (British) English phonetics for Poles. It clearly explains the basics of articulatory phonetics, discusses English pronunciation in detail and analyses the causes of pronunciation errors made by Poles at various stages of learning English. On this basis advice is offered on how to avoid pronunciation errors and significantly improve phonetics skills. The English of the book is adjusted to the intermediate reader, so that it is both precise and readable. The style is not devoid of humor.\r\nThe book is a must for a wide range of readers:\r\n-	students of English philology at an acadenmic level,\r\n-	students of English language colleges of education,\r\n-	all learners of English in schools, courses, or self taught,\r\n-	all those interested in the phonetics of English.\r\n\r\nThe unique feature of the book is the use of electronic dictionaires of English for the selection and presentation of the lexical material. The text is illustrated with a few thousand English words arranged by phonetic, grammatical and frequency criteria, and collected in over a hundred “boxes”.\r\n', 'product_image/English_Phonetics_for_Polses_SOBKOWIAK_d_s.jpg', 'product_image/English_Phonetics_for_Polses_SOBKOWIAK_d.jpg', NULL, 41.0000, 5, 500, 'ACTIVE'),
	(3199, 'Liliana Sikorska', 'This book is a thoroughly revised and enlarged version of An Outline History of English Literature, the second edition of which appeared in 2002. It provides a survey of English literature from Old English to the present day. The material covers major literary epochs, and each chapter is provided with a general introduction to the most important literary movements of the period followed by a more detailed examination of given authors and their works. At the end of each chapter the reader finds suggestions for further reading. This book offers a readable account of the history of English literature in English for Polish students. The emphasis has been placed on factual rather than analytical data, and therefore it is hoped that it can be of interest both to students of English and the general reader who needs a reference to particular literary periods and trends.This book is a thoroughly revised and enlarged version of An Outline History of English Literature, the second edition of which appeared in 2002. It provides a survey of English literature from Old English to the present day. The material covers major literary epochs, and each chapter is provided with a general introduction to the most important literary movements of the period followed by a more detailed examination of given authors and their works. At the end of each chapter the reader finds suggestions for further reading. This book offers a readable account of the history of English literature in English for Polish students. The emphasis has been placed on factual rather than analytical data, and therefore it is hoped that it can be of interest both to students of English and the general reader who needs a reference to particular literary periods and trends.', 'product_image/Liliana_Sikorska_sikorska_2007_d_s.jpg', 'product_image/Liliana_Sikorska_sikorska_2007_d.jpg', NULL, 50.0000, 5, 200, 'ACTIVE'),
	(9640, 'CONVERSATION STRATEGIES', 'CONVERSATION STRATEGIES (poziom A2-B1)\r\nTa książka to doskonały materiał do ćwiczenia konwersacji w parach, z takimi funkcjami jak:\r\n&bull; Wyrażanie opinii\r\n&bull; Wyjaśnianie nieporozumień\r\n&bull; Potwierdzanie za pomocą pytań\r\n&bull; Zgadzanie się lub niezgadzanie się z opinią partnera\r\n&bull; Rozpoczynanie rozmowy\r\n&bull; Podtrzymywanie rozmowy\r\n&bull; &bdquo;ucinanie&rdquo; tematu\r\n&bull; Rozmowy telefoniczne i wiele innych.\r\n\r\nKsiążka jest doskonała dla słuchaczy, kt&oacute;rzy doświadczają jeszcze tzw. bariery w m&oacute;wieniu, ponieważ nie wymaga od nich wyjątkowej kreatywności: zar&oacute;wno wypowiedzi czy pytania kierowane do partnera, jak i odpowiedzi i reakcje na to, co m&oacute;wi druga strona, są w książce podane jako konkretne propozycje. To z kolei stymuluje rozmowę i inspiruje do zadania dodatkowych pytań.', 'product_image/CONVERSATION_STRATEGIES_Conversation_Strategies_s.jpg', 'product_image/CONVERSATION_STRATEGIES_Conversation_Strategies.jpg', NULL, 55.0000, 5, 4, 'ACTIVE'),
	(9642, 'WRITING INSPIRATIONS (photocopiable)', 'WRITING INSPIRATIONS (poziomy od podstawowego do zaawansowanego &ndash; A2-B2) Ta książka to doskonały materiał do ćwiczenia umiejętności pisania, istne bogactwo ćwiczeń, kt&oacute;re można wykorzystać NIE TYLKO JAKO POMYSŁY NA PRACĘ DOMOWĄ, ale także ćwiczenia do przeprowadzenia podczas lekcji. R&oacute;żnorodność i wyb&oacute;r ćwiczeń są tutaj ogromne: słuchacze rozwijają umiejętność budowania wypowiedzi pisemnych za pomocą zadań polegających na napisaniu kilku przykładowych zdań; opisu zdjęcia lub obrazka; napisaniu kr&oacute;tkiej historii; e-maila; akapitu; kr&oacute;tkiego artykułu. W każdym ćwiczeniu słuchacz otrzymuje szereg wskaz&oacute;wek, w postaci listy wyrażeń lub pytań pomocnych w skomponowaniu wypowiedzi pisemnej. Ponieważ zadania są bardzo kr&oacute;tkie i treściwe, nie zajmują dużo czasu, co z kolei pozwala ćwiczyć pisanie na lekcji bez groźby narażenia się na zarzut, że większa część lekcji nie jest poświęcona na ćwiczenie m&oacute;wienia. Tym bardziej, że zadania zawarte w książce r&oacute;wnież nadają się do ćwiczeń konwersacyjnych.WRITING INSPIRATIONS (poziomy od podstawowego do zaawansowanego &ndash; A2-B2) Ta książka to doskonały materiał do ćwiczenia umiejętności pisania, istne bogactwo ćwiczeń, kt&oacute;re można wykorzystać NIE TYLKO JAKO POMYSŁY NA PRACĘ DOMOWĄ, ale także ćwiczenia do przeprowadzenia podczas lekcji. R&oacute;żnorodność i wyb&oacute;r ćwiczeń są tutaj ogromne: słuchacze rozwijają umiejętność budowania wypowiedzi pisemnych za pomocą zadań polegających na napisaniu kilku przykładowych zdań; opisu zdjęcia lub obrazka; napisaniu kr&oacute;tkiej historii; e-maila; akapitu; kr&oacute;tkiego artykułu. W każdym ćwiczeniu słuchacz otrzymuje szereg wskaz&oacute;wek, w postaci listy wyrażeń lub pytań pomocnych w skomponowaniu wypowiedzi pisemnej. Ponieważ zadania są bardzo kr&oacute;tkie i treściwe, nie zajmują dużo czasu, co z kolei pozwala ćwiczyć pisanie na lekcji bez groźby narażenia się na zarzut, że większa część lekcji nie jest poświęcona na ćwiczenie m&oacute;wienia. Tym bardziej, że zadania zawarte w książce r&oacute;wnież nadają się do ćwiczeń konwersacyjnych.', 'product_image/WRITING_INSPIRATIONS_Writing_Inspirations_s.jpg', 'product_image/WRITING_INSPIRATIONS_Writing_Inspirations.jpg', NULL, 75.0000, 5, 3, 'ACTIVE'),
	(9647, 'A PHRASAL VERB AFFAIR (+CD) SUPER PROMOCJA!', 'A PHRASAL VERB AFFAIR (poziom B1, B2) Phrasal verbs, czyli wyrażenia, w kt&oacute;rych czasowniki występują z przyimkami tworząc w ten spos&oacute;b całość to zmora wszystkich tych, kt&oacute;rzy uczą się języka angielskiego. Wielu uczni&oacute;w zgadza się co do tego, że tzw Phrasal Verbs to najtrudniejsze do zapamiętania struktury w tym języku. Powodem tego jest ich ogromna ilość oraz to, że często mają po kilka, zupełnie odmiennych znaczeń. Z &bdquo;A Phrasal Verb Affair&rdquo; uczenie się tych wyrażeń jest zupełnie proste. Książka składa się z 15 rozdział&oacute;w, każdy z nich jest kontynuacją poprzedniego, a wszystkie układają się w sp&oacute;jną całość, kt&oacute;rą stanowi historia pewnego małżeństwa przeżywającego kryzys. Na początku każdego rozdziału mamy zatem scenę rodem z mydlanej opery, w kt&oacute;rej bohaterowie rozmawiają, używając szeregu &bdquo;phrasal verbs.&rdquo; To sprawia, że zrozumienie znaczenia tych wyrażeń nie stanowi dużej trudności, bo będąc świadkami danej scenki, słuchając aktor&oacute;w, śledzimy cały kontekst ich wypowiedzi. Po każdym dialogu dostajemy kilka dodatkowych ćwiczeń, w kt&oacute;rych wszystkie wprowadzone &bdquo;phrasal verbs&rdquo; są przedstawione w innych, doskonale je ilustrujących przykładach. Ponadto, jeśli ktoś zastanawiał się, jak po angielsku brzmią tak popularne, potoczne wyrażenia, jak: &bdquo;zbywać kogoś,&rdquo; &bdquo;wygarnąć komuś,&rdquo; &bdquo;uwziąć się na kogoś,&rdquo; &bdquo;wydobywać w kimś to, co najlepsze,&rdquo; &bdquo;co Ci strzeliło do głowy?!&rdquo; i wiele innych, to z tej książki na pewno szybko się tego dowie. &bdquo;A Phrasal Verb Affair&rdquo; to absolutny hit, zar&oacute;wno dla nauczycieli, jak i dla uczących się. Znajdziemy tutaj ponad 200 &bdquo;phrasal verbs&rdquo; w prostych i jednocześnie niezwykle pomocnych ćwiczeniach.A PHRASAL VERB AFFAIR (poziom B1, B2) Phrasal verbs, czyli wyrażenia, w kt&oacute;rych czasowniki występują z przyimkami tworząc w ten spos&oacute;b całość to zmora wszystkich tych, kt&oacute;rzy uczą się języka angielskiego. Wielu uczni&oacute;w zgadza się co do tego, że tzw Phrasal Verbs to najtrudniejsze do zapamiętania struktury w tym języku. Powodem tego jest ich ogromna ilość oraz to, że często mają po kilka, zupełnie odmiennych znaczeń. Z &bdquo;A Phrasal Verb Affair&rdquo; uczenie się tych wyrażeń jest zupełnie proste. Książka składa się z 15 rozdział&oacute;w, każdy z nich jest kontynuacją poprzedniego, a wszystkie układają się w sp&oacute;jną całość, kt&oacute;rą stanowi historia pewnego małżeństwa przeżywającego kryzys. Na początku każdego rozdziału mamy zatem scenę rodem z mydlanej opery, w kt&oacute;rej bohaterowie rozmawiają, używając szeregu &bdquo;phrasal verbs.&rdquo; To sprawia, że zrozumienie znaczenia tych wyrażeń nie stanowi dużej trudności, bo będąc świadkami danej scenki, słuchając aktor&oacute;w, śledzimy cały kontekst ich wypowiedzi. Po każdym dialogu dostajemy kilka dodatkowych ćwiczeń, w kt&oacute;rych wszystkie wprowadzone &bdquo;phrasal verbs&rdquo; są przedstawione w innych, doskonale je ilustrujących przykładach. Ponadto, jeśli ktoś zastanawiał się, jak po angielsku brzmią tak popularne, potoczne wyrażenia, jak: &bdquo;zbywać kogoś,&rdquo; &bdquo;wygarnąć komuś,&rdquo; &bdquo;uwziąć się na kogoś,&rdquo; &bdquo;wydobywać w kimś to, co najlepsze,&rdquo; &bdquo;co Ci strzeliło do głowy?!&rdquo; i wiele innych, to z tej książki na pewno szybko się tego dowie. &bdquo;A Phrasal Verb Affair&rdquo; to absolutny hit, zar&oacute;wno dla nauczycieli, jak i dla uczących się. Znajdziemy tutaj ponad 200 &bdquo;phrasal verbs&rdquo; w prostych i jednocześnie niezwykle pomocnych ćwiczeniach.', 'product_image/A_PHRASAL_VERB_AFFAIR_(CD_A_Phrasal_Verb_Affair_s.jpg', 'product_image/A_PHRASAL_VERB_AFFAIR_(CD_A_Phrasal_Verb_Affair.jpg', NULL, 88.5000, 5, 4, 'ACTIVE'),
	(9648, 'DICTATIONS FOR DISCUSSION (+2CD)', 'DICTATIONS FOR DISCUSSION (poziom B2)\r\n\r\nW tej książce znajdziemy ponad 50 dyktowanych tekst&oacute;w w czterech formatach. Są tu zatem ćwiczenia polegające na uzupełnianiu wysłuchanego tekstu; ćwiczenia w parach, polegające na wzajemnym dyktowaniu tekstu przez słuchaczy; tzw dictogloss &ndash; ćwiczenie polegające na streszczeniu wysłuchanego tekstu; ćwiczenia, w kt&oacute;rych przed wysłuchaniem tekstu słuchacze mają za zadanie przewidzieć, jakie są brakujące informacje.\r\n\r\nTeksty do tego materiału zostały wybrane spośr&oacute;d r&oacute;żnorodnych autentycznych źr&oacute;deł &ndash; czasopism, gazet, Internetu. Po wysłuchaniu i uzupełnieniu tekstu jest czas na ciekawą dyskusję, bo artykuły w książce poruszają zagadnienia z takich kategorii tematycznych jak:\r\n&bull; Kultura\r\n&bull; Pieniądze i kariera\r\n&bull; Święta i szczeg&oacute;lne wydarzenia\r\n&bull; Etyka\r\n&bull; Zdrowie\r\n&bull; Ciekawostki na temat języka angielskiego', 'product_image/DICTATIONS_FOR_DISCUSSION_(2CD_Dictations_For_Discussion_s.jpg', 'product_image/DICTATIONS_FOR_DISCUSSION_(2CD_Dictations_For_Discussion.jpg', NULL, 93.0000, 5, 5, 'ACTIVE'),
	(9651, 'THE MODAL BOOK', 'Opis polski 14 rozdział&oacute;w w tej książce zawierają liczne i urozmaicone ćwiczenia służące lepszemu zrozumieniu czasownik&oacute;w modalnych. Każdy rozdział rozpoczyna tekst opisujący ciekawostki z egzotycznego kraju, m.in. Ekwadoru czy Tajlandii. W tekście oczywiście mamy szereg modalnych użytych w konkretnych kontekstach. Książka jest doskonała jako samouczek i jako materiał do wykorzystania na lekcji.Opis polski 14 rozdział&oacute;w w tej książce zawierają liczne i urozmaicone ćwiczenia służące lepszemu zrozumieniu czasownik&oacute;w modalnych. Każdy rozdział rozpoczyna tekst opisujący ciekawostki z egzotycznego kraju, m.in. Ekwadoru czy Tajlandii. W tekście oczywiście mamy szereg modalnych użytych w konkretnych kontekstach. Książka jest doskonała jako samouczek i jako materiał do wykorzystania na lekcji.', 'product_image/THE_MODAL_BOOK_The_Modal_Book_s.jpg', 'product_image/THE_MODAL_BOOK_The_Modal_Book.jpg', NULL, 58.0000, 5, 5, 'ACTIVE'),
	(9654, 'English Teaching Professional - roczna prenumerata', 'Dwumiesięcznik „English Teaching Professional” to renomowany magazyn metodyczny tworzony przez profesjonalistów dla profesjonalistów. \r\n\r\nTematyka czasopismo koncentruje się na krytycznej analizie bieżących trendów w nauczaniu języka angielskiego oraz przeglądzie najnowszych narzędzi metodycznych. \r\nRedaktorzy pisma wiele uwagi skupiają na nowoczesnych technologiach, używanych w pracy nauczyciela, takich jak video, multimedia czy internet. „ETP” to także kopalnia wiedzy o nowatorskich warsztatach, szkoleniach i publikacjach. Lektura światowej klasy metodyków nie pozwala zostać w tyle w żadnej z szerokich dziedzin English Langauge Teaching.\r\nCzytając „ETP” nie tylko zyskujemy ciekawe i praktyczne materiały na lekcje, ale także systematycznie rozwijamy warsztat oraz uczymy się planować i osiągać zamierzone cele dydaktyczne. Jest to pismo dla anglistów pracujących z pasją i zaangażowaniem, stawiających na swój zawodowy rozwój. \r\n\r\nUWAGA. Teraz zamawiając prenumeratę otrzymasz gratis readers z płytami audio – CD!Dwumiesięcznik „English Teaching Professional” to renomowany magazyn metodyczny tworzony przez profesjonalistów dla profesjonalistów. \r\n\r\nTematyka czasopismo koncentruje się na krytycznej analizie bieżących trendów w nauczaniu języka angielskiego oraz przeglądzie najnowszych narzędzi metodycznych. \r\nRedaktorzy pisma wiele uwagi skupiają na nowoczesnych technologiach, używanych w pracy nauczyciela, takich jak video, multimedia czy internet. „ETP” to także kopalnia wiedzy o nowatorskich warsztatach, szkoleniach i publikacjach. Lektura światowej klasy metodyków nie pozwala zostać w tyle w żadnej z szerokich dziedzin English Langauge Teaching.\r\nCzytając „ETP” nie tylko zyskujemy ciekawe i praktyczne materiały na lekcje, ale także systematycznie rozwijamy warsztat oraz uczymy się planować i osiągać zamierzone cele dydaktyczne. Jest to pismo dla anglistów pracujących z pasją i zaangażowaniem, stawiających na swój zawodowy rozwój. \r\n\r\nUWAGA. Teraz zamawiając prenumeratę otrzymasz gratis readers z płytami audio – CD!', 'product_image/English_Teaching_Professional_-_roczna_prenumerata_ETP_66_s.jpg', 'product_image/English_Teaching_Professional_-_roczna_prenumerata_ETP_66.jpg', NULL, 115.0000, 5, 4, 'ACTIVE'),
	(9655, 'Modern English Teacher - roczna prenumerata', '„Modern English Teacher” to znakomity przewodnik dla osób chcących uczyć angielskiego nowocześnie i skutecznie.\r\n30 letni magazyn dla nauczycieli języka angielskiego jest na rynku pozycją kultową. To tutaj specjaliści z różnych części świata dzielą się swoimi doświadczeniami, stwarzając możliwość konfrontacji różnych metodologii nauczania języka angielskiego.\r\nW każdym wydanie kwartalnika znajdziemy obszerna sekcje poświęconą praktycznym rozwiązaniom metodycznym oraz specjalistyczne artykuły z obszarów lingwistyki i psychologii. Materiały zawarte w „Modern English Teacher” odznaczają się najwyższą jakością i profesjonalizmem.\r\nWarto także zwrócić również uwagę na rozbudowaną sekcje recenzji. Jeśli szukasz dobrych publikacji książkowych, „Modern English Teacher” będzie idealnym przewodnikiem.\r\n\r\nUWAGA. Teraz zamawiając prenumeratę otrzymasz gratis readers z płytami audio – CD!„Modern English Teacher” to znakomity przewodnik dla osób chcących uczyć angielskiego nowocześnie i skutecznie.\r\n30 letni magazyn dla nauczycieli języka angielskiego jest na rynku pozycją kultową. To tutaj specjaliści z różnych części świata dzielą się swoimi doświadczeniami, stwarzając możliwość konfrontacji różnych metodologii nauczania języka angielskiego.\r\nW każdym wydanie kwartalnika znajdziemy obszerna sekcje poświęconą praktycznym rozwiązaniom metodycznym oraz specjalistyczne artykuły z obszarów lingwistyki i psychologii. Materiały zawarte w „Modern English Teacher” odznaczają się najwyższą jakością i profesjonalizmem.\r\nWarto także zwrócić również uwagę na rozbudowaną sekcje recenzji. Jeśli szukasz dobrych publikacji książkowych, „Modern English Teacher” będzie idealnym przewodnikiem.\r\n\r\nUWAGA. Teraz zamawiając prenumeratę otrzymasz gratis readers z płytami audio – CD!', 'product_image/Modern_English_Teacher_-_roczna_prenumerata_MET_19_1_s.jpg', 'product_image/Modern_English_Teacher_-_roczna_prenumerata_MET_19_1.jpg', NULL, 125.0000, 5, 9, 'ACTIVE'),
